    public static string GetPathData(string key)
    {
        if (string.IsNullOrWhiteSpace(key))
            return "M0,0";

        var cleanKey = key.Trim();
        if (cleanKey.StartsWith("mdi:", StringComparison.OrdinalIgnoreCase))
            cleanKey = cleanKey[4..];
        else if (cleanKey.StartsWith("app:", StringComparison.OrdinalIgnoreCase))
            cleanKey = cleanKey[4..];

        if (Icons.TryGetValue(cleanKey, out var path))
            return path;

        return "M12,2A10,10 0 1,0 22,12A10,10 0 0,0 12,2Z"; // Default circle
    }

    public static bool HasIcon(string key)
    {
        if (string.IsNullOrWhiteSpace(key)) return false;
        var cleanKey = key.Trim();
        if (cleanKey.StartsWith("mdi:", StringComparison.OrdinalIgnoreCase))
            cleanKey = cleanKey[4..];
        return Icons.ContainsKey(cleanKey);
    }
}
